sys_script_include.script:
var GlobalToolsScriptedRESTDoc = Class.create(); 
GlobalToolsScriptedRESTDoc.prototype = {
	initialize: function (gtCache, oTimer) {
		if (!this._checkAccess(gs.getCallerScopeName())) { return; }
		if (gtCache instanceof GlobalToolsCache) {
			this._gtCache = gtCache;
		} else {
			this._gtCache = new global.GlobalToolsCache();
		} // if cache
		this.bTimer = ((oTimer) && ((oTimer === true) || (oTimer instanceof GlobalToolsDateTime))) ? true : false;
		if (this.bTimer) {
			this._gtDateTime = (oTimer === true) ? new global.GlobalToolsDateTime('gtrd') : oTimer;
			this._sTimerPrefix = (oTimer === true) ? '' : 'gtrd/';
		} // if timer
		this._gt = new global.GlobalTools();
		this._gtObject = new global.GlobalToolsObject();
		this._getValue = this._gtObject.getValue;
		this._gtArray = new global.GlobalToolsArray();
		this._gtTable = new global.GlobalToolsTable(this._gtCache, this._gtDateTime);
		this.sMarker = '[gt-doc]';
		this.sSchemaPrefix = 'gt_';
		this.sErrorSchemaName = 'gt_GlobalToolsScriptedREST.error';
		this.sOpenApiVersion = '3.0.1';
		this.iQueryParameterNameMaxLength = 40;
		this.iQueryParameterDescriptionMaxLength = 80;
		this.aRequiredRoles = ['web_service_admin', 'admin'];
		this.aReservedQueryParameters = ['encoded_query', 'history_walk', 'max_return_items', 'return_offset', 'requested_fields', 'orderby_fields', 'orderbydesc_fields'];
		this.oOptionTypes = { 'oResourceConfigMap': 'object', 'aResourceIds': 'array', 'sVersion': 'string', 'sRecordScope': 'string', 'bDryRun': 'boolean', 'bRemoveStale': 'boolean', 'bOverwriteManual': 'boolean', 'bDocumentFieldFilters': 'boolean', 'bIncludeChoiceEnum': 'boolean' };
		this.oOptionDefaults = { 'oResourceConfigMap': {}, 'aResourceIds': [], 'sVersion': '', 'sRecordScope': 'global', 'bDryRun': false, 'bRemoveStale': true, 'bOverwriteManual': false, 'bDocumentFieldFilters': false, 'bIncludeChoiceEnum': true };
	}, // function initialize

	_checkAccess: function (sCallerScope) {
		if (this.oAllowedScopes) { return this.oAllowedScopes.hasOwnProperty(String(sCallerScope)); }
		var aScopes = String(gs.getProperty('now.globaltools.access_from_scope')).split(',');
		var aCustomScopes = String(gs.getProperty('now.globaltools.access_from_scope_custom')).split(',');
		this.oAllowedScopes = Object.fromEntries([...aScopes, ...aCustomScopes].map(sItem => [sItem, true]));
		this.oAllowedScopes['rhino.global'] = true;
		return this.oAllowedScopes.hasOwnProperty(String(sCallerScope));
	}, // function _checkAccess

	/***********************************************************************************************************
	*	Public entry points
	************************************************************************************************************/

	populateApiDocumentation: function (sApiIdentifier, oOptions) {
		if (!this._checkAccess(gs.getCallerScopeName())) { return; }
		if (this.bTimer) { this._gtDateTime.startTimer(this._sTimerPrefix + 'populateApiDocumentation'); }
		var oResult = { 'bIsOk': true, 'aCreated': [], 'aUpdated': [], 'aDeleted': [], 'aUnchanged': [], 'aSkipped': [], 'aConflicts': [], 'aWarnings': [], 'sErrorMessage': '' };
		try {
			this._populate(sApiIdentifier, oOptions, oResult);
		} catch (oException) {
			oResult['bIsOk'] = false;
			oResult['sErrorMessage'] = 'Unexpected error: ' + String(oException);
		} // try populate
		if (this.bTimer) { this._gtDateTime.stopTimer(this._sTimerPrefix + 'populateApiDocumentation'); }
		return oResult;
	}, // function populateApiDocumentation

	removeApiDocumentation: function (sApiIdentifier, oOptions) {
		if (!this._checkAccess(gs.getCallerScopeName())) { return; }
		var oResult = { 'bIsOk': true, 'aCreated': [], 'aUpdated': [], 'aDeleted': [], 'aUnchanged': [], 'aSkipped': [], 'aConflicts': [], 'aWarnings': [], 'sErrorMessage': '' };
		try {
			this._remove(sApiIdentifier, oOptions, oResult);
		} catch (oException) {
			oResult['bIsOk'] = false;
			oResult['sErrorMessage'] = 'Unexpected error: ' + String(oException);
		} // try remove
		return oResult;
	}, // function removeApiDocumentation

	buildResourceDocumentation: function (oResolvedConfig, sEntryPoint, oOperationInfo) {
		if (!this._checkAccess(gs.getCallerScopeName())) { return; }
		var oPlan = { 'bIsOk': true, 'sErrorMessage': '', 'aSchemas': [], 'oRequest': null, 'aResponses': [], 'aQueryParameters': [], 'aWarnings': [] };
		if (!this.aRequiredRoles.some(sRole => gs.hasRole(sRole))) {
			oPlan['bIsOk'] = false;
			oPlan['sErrorMessage'] = 'Role ' + this.aRequiredRoles.join(' or ') + ' is required';
			return oPlan;
		} // if role missing
		if (!this._gtObject.isObject(oResolvedConfig)) {
			oPlan['bIsOk'] = false;
			oPlan['sErrorMessage'] = 'Resolved configuration is not an object';
			return oPlan;
		} // if no config
		if ((sEntryPoint != 'getData') && (sEntryPoint != 'setData')) {
			oPlan['bIsOk'] = false;
			oPlan['sErrorMessage'] = 'Entry point must be getData or setData, got: ' + String(sEntryPoint);
			return oPlan;
		} // if invalid entry point
		var oInfo = (this._gtObject.isObject(oOperationInfo)) ? oOperationInfo : {};
		var sResourceKey = this._sanitizeName(this._getValue('sResourceKey', this._getValue('sName', 'resource', oInfo), oInfo));
		var sConfigName = String(this._getValue('sConfigName', '', oInfo));
		var oOptions = this._getValue('oOptions', {}, oInfo);
		var sSource = (sConfigName) ? ' from JSON Configuration ' + sConfigName : '';
		if (sEntryPoint == 'getData') {
			var sReadSchemaName = this.sSchemaPrefix + sResourceKey + '.read.response';
			var oReadSchema = this._buildReadResponseSchema(oResolvedConfig, oOptions, oPlan);
			oPlan['aSchemas'].push({ 'sName': sReadSchemaName, 'oSchema': oReadSchema, 'sDescription': 'Response of resource ' + sResourceKey + sSource });
			oPlan['aQueryParameters'] = this._buildQueryParameters(oResolvedConfig, oOptions, oPlan);
			oPlan['aResponses'].push({ 'iHttpStatus': 200, 'sSchemaName': sReadSchemaName, 'sDescription': this._buildReadSuccessDescription(oResolvedConfig) });
		} else {
			var sAction = String(this._getValue('sAction', '', oResolvedConfig));
			var sRequestSchemaName = this.sSchemaPrefix + sResourceKey + '.' + this._sanitizeName(sAction || 'write') + '.request';
			var sResponseSchemaName = this.sSchemaPrefix + sResourceKey + '.' + this._sanitizeName(sAction || 'write') + '.response';
			oPlan['aSchemas'].push({ 'sName': sRequestSchemaName, 'oSchema': this._buildWriteRequestSchema(oResolvedConfig, oPlan), 'sDescription': 'Request body of resource ' + sResourceKey + sSource });
			oPlan['aSchemas'].push({ 'sName': sResponseSchemaName, 'oSchema': this._buildWriteResponseSchema(oResolvedConfig), 'sDescription': 'Response of resource ' + sResourceKey + sSource });
			oPlan['oRequest'] = { 'sSchemaName': sRequestSchemaName, 'sDescription': 'Request body for action ' + sAction + ' on ' + Object.keys(this._getValue('oTables', {}, oResolvedConfig)).join(', ') };
			oPlan['aResponses'].push({ 'iHttpStatus': (sAction == 'insert') ? 201 : 200, 'sSchemaName': sResponseSchemaName, 'sDescription': 'Write result for action ' + sAction });
		} // if read or write
		oPlan['aSchemas'].push({ 'sName': this.sErrorSchemaName, 'oSchema': this._buildErrorSchema(), 'sDescription': 'Error body of GlobalToolsScriptedREST (sn_ws_err.ServiceError)', 'bShared': true });
		this._buildErrorResponses(oResolvedConfig, sEntryPoint).forEach(function (oErrorResponse) {
			oPlan['aResponses'].push(oErrorResponse);
		}, this); // each error response
		return oPlan;
	}, // function buildResourceDocumentation

	/***********************************************************************************************************
	*	Orchestration
	************************************************************************************************************/

	_populate: function (sApiIdentifier, oOptions, oResult) {
		if (!this._checkAccess(gs.getCallerScopeName())) { return; }
		var oValidOptions = this._validateOptions(oOptions, oResult);
		if (!oResult['bIsOk']) {
			return;
		} // if invalid options
		if (!this.aRequiredRoles.some(sRole => gs.hasRole(sRole))) {
			oResult['bIsOk'] = false;
			oResult['sErrorMessage'] = 'Role ' + this.aRequiredRoles.join(' or ') + ' is required';
			return;
		} // if role missing
		var oApi = this._getApi(sApiIdentifier);
		if (!oApi) {
			oResult['bIsOk'] = false;
			oResult['sErrorMessage'] = 'Unknown API: ' + String(sApiIdentifier);
			return;
		} // if unknown api
		if (oApi['sScope'] != 'global') {
			oResult['aWarnings'].push({ 'sTable': 'sys_ws_definition', 'sKey': oApi['sName'], 'sSysId': oApi['sSysId'], 'sReason': 'API is not in global scope; records are still written in global (unverified for scoped APIs, Q2)' });
		} // if scoped api
		var oScopeCheck = this._checkTargetScope();
		if (!oScopeCheck['bIsOk']) {
			if (oValidOptions['bDryRun']) {
				oResult['aWarnings'].push({ 'sTable': 'sys_update_set', 'sKey': oScopeCheck['sUpdateSetName'], 'sSysId': oScopeCheck['sUpdateSetId'], 'sReason': oScopeCheck['sMessage'] });
			} else {
				oResult['bIsOk'] = false;
				oResult['sErrorMessage'] = oScopeCheck['sMessage'];
				return;
			} // if dry run
		} // if scope mismatch
		var oApiPlan = this._planApi(oApi, oValidOptions, oResult);
		if (!oResult['bIsOk']) {
			return;
		} // if planning failed
		if (oApiPlan['aOperations'].length == 0) {
			oResult['bIsOk'] = false;
			oResult['sErrorMessage'] = 'API ' + oApi['sName'] + ' has no in-scope resource (GlobalToolsScriptedREST getData or setData with a JSON Configuration)';
			return;
		} // if nothing in scope
		this._validatePlannedSchemas(oApi, oApiPlan, oResult);
		if (!oResult['bIsOk']) {
			return;
		} // if invalid schema
		var aActions = this._diffApiPlan(oApi, oApiPlan, oValidOptions, oResult);
		if (oValidOptions['bDryRun']) {
			this._reportActions(aActions, oResult);
			return;
		} // if dry run
		this._executeActions(aActions, oResult);
	}, // function _populate

	_remove: function (sApiIdentifier, oOptions, oResult) {
		if (!this._checkAccess(gs.getCallerScopeName())) { return; }
		var bDryRun = true;
		if ((oOptions !== undefined) && (oOptions !== null)) {
			if ((!this._gtObject.isObject(oOptions)) || (Object.keys(oOptions).some(sOption => sOption != 'bDryRun')) || ((oOptions.hasOwnProperty('bDryRun')) && (typeof oOptions['bDryRun'] != 'boolean'))) {
				oResult['bIsOk'] = false;
				oResult['sErrorMessage'] = 'Invalid oOptions: only bDryRun (boolean, default true) is supported';
				return;
			} // if invalid options
			bDryRun = (oOptions.hasOwnProperty('bDryRun')) ? oOptions['bDryRun'] : true;
		} // if options
		if (!this.aRequiredRoles.some(sRole => gs.hasRole(sRole))) {
			oResult['bIsOk'] = false;
			oResult['sErrorMessage'] = 'Role ' + this.aRequiredRoles.join(' or ') + ' is required';
			return;
		} // if role missing
		var oApi = this._getApi(sApiIdentifier);
		if (!oApi) {
			oResult['bIsOk'] = false;
			oResult['sErrorMessage'] = 'Unknown API: ' + String(sApiIdentifier);
			return;
		} // if unknown api
		var oScopeCheck = this._checkTargetScope();
		if (!oScopeCheck['bIsOk']) {
			if (bDryRun) {
				oResult['aWarnings'].push({ 'sTable': 'sys_update_set', 'sKey': oScopeCheck['sUpdateSetName'], 'sSysId': oScopeCheck['sUpdateSetId'], 'sReason': oScopeCheck['sMessage'] });
			} else {
				oResult['bIsOk'] = false;
				oResult['sErrorMessage'] = oScopeCheck['sMessage'];
				return;
			} // if dry run
		} // if scope mismatch
		var oStaleOptions = { 'bRemoveStale': true };
		var aActions = [];
		var aParameters = this._readRecords('sys_ws_query_parameter', 'web_service_definition=' + oApi['sSysId'] + '^short_descriptionLIKE' + this.sMarker, ['name']);
		if (aParameters.length > 0) {
			var oParameterNames = {};
			aParameters.forEach(function (oParameter) {
				oParameterNames[oParameter['sys_id']] = oParameter['name'];
			}); // index parameter names
			this._readRecords('sys_ws_query_parameter_map', 'web_service_query_parameterIN' + Object.keys(oParameterNames).join(','), ['web_service_operation', 'web_service_query_parameter']).forEach(function (oMap) {
				this._planStale(aActions, 'sys_ws_query_parameter_map', oMap['web_service_operation'] + '|' + oParameterNames[oMap['web_service_query_parameter']], oMap, oStaleOptions, 50);
			}, this); // each generated parameter map
			aParameters.forEach(function (oParameter) {
				this._planStale(aActions, 'sys_ws_query_parameter', oApi['sName'] + '|' + oParameter['name'], oParameter, oStaleOptions, 20);
			}, this); // each generated parameter
		} // if generated parameters
		[
			{ 'sTable': 'sys_ws_response_spec', 'sQuery': 'api=' + oApi['sName'] + '^descriptionLIKE' + this.sMarker, 'iOrder': 40 },
			{ 'sTable': 'sys_ws_request_spec', 'sQuery': 'api=' + oApi['sName'] + '^descriptionLIKE' + this.sMarker, 'iOrder': 30 },
			{ 'sTable': 'sys_ws_schema', 'sQuery': 'api=' + oApi['sName'] + '^nameSTARTSWITH' + this.sSchemaPrefix + '^descriptionLIKE' + this.sMarker, 'iOrder': 10 }
		].forEach(function (oTarget) {
			this._readRecords(oTarget['sTable'], oTarget['sQuery'], ['name']).forEach(function (oRecord) {
				this._planStale(aActions, oTarget['sTable'], oApi['sName'] + '|' + ((oRecord['name']) ? oRecord['name'] : oRecord['sys_id']), oRecord, oStaleOptions, oTarget['iOrder']);
			}, this); // each generated record
		}, this); // each target table
		if (bDryRun) {
			this._reportActions(aActions, oResult);
			return;
		} // if dry run
		this._executeActions(aActions, oResult);
	}, // function _remove

	_validateOptions: function (oOptions, oResult) {
		if (!this._checkAccess(gs.getCallerScopeName())) { return; }
		var oValidOptions = JSON.parse(JSON.stringify(this.oOptionDefaults));
		if ((oOptions === undefined) || (oOptions === null)) {
			return oValidOptions;
		} // if no options
		if (!this._gtObject.isObject(oOptions)) {
			oResult['bIsOk'] = false;
			oResult['sErrorMessage'] = 'Invalid oOptions: expected an object';
			return oValidOptions;
		} // if not object
		Object.keys(oOptions).some(function (sOption) {
			if (!this.oOptionTypes.hasOwnProperty(sOption)) {
				oResult['bIsOk'] = false;
				oResult['sErrorMessage'] = 'Invalid option: ' + sOption;
				return true;
			} // if unknown option
			var sExpectedType = this.oOptionTypes[sOption];
			var sActualType = (Array.isArray(oOptions[sOption])) ? 'array' : typeof oOptions[sOption];
			if (sActualType != sExpectedType) {
				oResult['bIsOk'] = false;
				oResult['sErrorMessage'] = 'Invalid option ' + sOption + ': expected ' + sExpectedType + ', got ' + sActualType;
				return true;
			} // if wrong type
			oValidOptions[sOption] = oOptions[sOption];
		}, this); // each option
		if (!oResult['bIsOk']) {
			return oValidOptions;
		} // if invalid
		var oNormalizedMap = {};
		Object.keys(oValidOptions['oResourceConfigMap']).some(function (sOperationId) {
			var oMapEntry = this._normalizeMapEntry(oValidOptions['oResourceConfigMap'][sOperationId]);
			if (oMapEntry['sError']) {
				oResult['bIsOk'] = false;
				oResult['sErrorMessage'] = 'Invalid oResourceConfigMap entry ' + sOperationId + ': ' + oMapEntry['sError'];
				return true;
			} // if invalid entry
			oNormalizedMap[sOperationId] = oMapEntry;
		}, this); // each map entry
		if (!oResult['bIsOk']) {
			return oValidOptions;
		} // if invalid map
		oValidOptions['oResourceConfigMap'] = oNormalizedMap;
		if (oValidOptions['sRecordScope'] == 'api') {
			oResult['bIsOk'] = false;
			oResult['sErrorMessage'] = 'sRecordScope "api" is not supported in version 1 (open question Q2); nothing was written';
		} else if (oValidOptions['sRecordScope'] != 'global') {
			oResult['bIsOk'] = false;
			oResult['sErrorMessage'] = 'Invalid option value sRecordScope: ' + oValidOptions['sRecordScope'] + ' (allowed: global, api)';
		} // if record scope
		return oValidOptions;
	}, // function _validateOptions

	_normalizeMapEntry: function (oEntry) {
		if (!this._checkAccess(gs.getCallerScopeName())) { return; }
		var oMapEntry = { 'aConfigs': [], 'sSelector': '', 'sError': '' };
		var oConfigs = null;
		if (typeof oEntry == 'string') {
			oConfigs = [oEntry];
		} else if (Array.isArray(oEntry)) {
			oConfigs = oEntry;
		} else if (this._gtObject.isObject(oEntry)) {
			var aUnknownKeys = Object.keys(oEntry).filter(function (sKey) { return (['aConfigs', 'sSelector'].indexOf(sKey) == -1); });
			if (aUnknownKeys.length > 0) {
				oMapEntry['sError'] = 'unknown key ' + aUnknownKeys.join(', ') + ' (allowed: aConfigs, sSelector)';
				return oMapEntry;
			} // if unknown keys
			oConfigs = (typeof oEntry['aConfigs'] == 'string') ? [oEntry['aConfigs']] : oEntry['aConfigs'];
			if ((oEntry.hasOwnProperty('sSelector')) && (typeof oEntry['sSelector'] != 'string')) {
				oMapEntry['sError'] = 'sSelector must be a string';
				return oMapEntry;
			} // if invalid selector
			oMapEntry['sSelector'] = String(this._getValue('sSelector', '', oEntry)).trim();
		} // if entry form
		if ((!Array.isArray(oConfigs)) || (oConfigs.length == 0)) {
			oMapEntry['sError'] = 'expected a configuration name, an array of names, or an object with aConfigs and an optional sSelector';
			return oMapEntry;
		} // if no configurations
		oConfigs.some(function (sConfig) {
			if ((typeof sConfig != 'string') || (sConfig.trim() === '')) {
				oMapEntry['sError'] = 'configuration names must be non-empty strings';
				return true;
			} // if invalid name
			if (oMapEntry['aConfigs'].indexOf(sConfig.trim()) != -1) {
				oMapEntry['sError'] = 'configuration ' + sConfig.trim() + ' is listed twice';
				return true;
			} // if duplicate
			oMapEntry['aConfigs'].push(sConfig.trim());
		}, this); // each configuration
		if ((!oMapEntry['sError']) && (oMapEntry['sSelector']) && (oMapEntry['aConfigs'].length < 2)) {
			oMapEntry['sError'] = 'sSelector needs at least two configurations in aConfigs';
		} // if selector without variants
		return oMapEntry;
	}, // function _normalizeMapEntry

	_getApi: function (sApiIdentifier) {
		if (!this._checkAccess(gs.getCallerScopeName())) { return; }
		var sIdentifier = String(sApiIdentifier || '');
		if ((!sIdentifier) || (sIdentifier.indexOf('^') != -1)) {
			return null;
		} // if empty or query metacharacter
		var grDefinition = new GlideRecord('sys_ws_definition');
		if (/^[0-9a-f]{32}$/.test(sIdentifier)) {
			if (!grDefinition.get(sIdentifier)) {
				return null;
			} // if not found
		} else if (sIdentifier.indexOf('/') != -1) {
			var aIdentifierParts = sIdentifier.replace(/^\/?(api\/)?/, '').split('/');
			grDefinition.addQuery('namespace', aIdentifierParts[0]);
			grDefinition.addQuery('service_id', aIdentifierParts[1]);
			grDefinition.setLimit(1);
			grDefinition.query();
			if (!grDefinition.next()) {
				return null;
			} // if not found
		} else {
			return null;
		} // if sys_id or namespace/service_id
		var sBaseUri = String(grDefinition.getValue('base_uri') || '');
		return {
			'sSysId': grDefinition.getUniqueValue(),
			'sName': String(grDefinition.getValue('name')),
			'sServiceId': String(grDefinition.getValue('service_id')),
			'sNamespace': String(grDefinition.getValue('namespace')),
			'sBaseUri': sBaseUri,
			'sApiPath': sBaseUri.replace(/^\/api\//, ''),
			'bIsVersioned': (String(grDefinition.getValue('is_versioned')) == '1'),
			'sScope': String(grDefinition.getValue('sys_scope'))
		}; // api info
	}, // function _getApi

	_checkTargetScope: function () {
		if (!this._checkAccess(gs.getCallerScopeName())) { return; }
		var oScopeCheck = { 'bIsOk': true, 'sMessage': '', 'sUpdateSetId': '', 'sUpdateSetName': '' };
		var sCurrentApplicationId = String(gs.getCurrentApplicationId());
		var _GlideUpdateSet = new GlideUpdateSet();
		var sUpdateSetId = String(_GlideUpdateSet.get());
		var grUpdateSet = new GlideRecord('sys_update_set');
		var sUpdateSetScope = '';
		if (grUpdateSet.get(sUpdateSetId)) {
			sUpdateSetScope = String(grUpdateSet.getValue('application'));
			oScopeCheck['sUpdateSetName'] = String(grUpdateSet.getValue('name'));
		} // if update set
		oScopeCheck['sUpdateSetId'] = sUpdateSetId;
		if ((sCurrentApplicationId != 'global') || (sUpdateSetScope != 'global')) {
			oScopeCheck['bIsOk'] = false;
			oScopeCheck['sMessage'] = 'Target scope is global, but the current application is ' + sCurrentApplicationId + ' and the current update set (' + oScopeCheck['sUpdateSetName'] + ') belongs to ' + sUpdateSetScope + '; switch to global before writing';
		} // if scope mismatch
		return oScopeCheck;
	}, // function _checkTargetScope

	_planApi: function (oApi, oOptions, oResult) {
		if (!this._checkAccess(gs.getCallerScopeName())) { return; }
		var oApiPlan = { 'aOperations': [], 'oSchemas': {}, 'aRequestSpecs': [], 'aResponseSpecs': [], 'oQueryParameters': {}, 'aParameterMaps': [], 'aResourceVersions': [] };
		var oVersions = this._getVersions(oApi);
		var aSelected = [];
		var grOperation = new GlideRecord('sys_ws_operation');
		grOperation.addQuery('web_service_definition', oApi['sSysId']);
		grOperation.addQuery('active', true);
		if (oOptions['aResourceIds'].length > 0) {
			grOperation.addQuery('sys_id', 'IN', oOptions['aResourceIds'].join(','));
		} // if resource filter
		grOperation.orderBy('name');
		grOperation.query();
		while (grOperation.next()) {
			var oOperationInfo = this._getOperationInfo(grOperation, oApi, oVersions, oOptions['sVersion']);
			if (oOperationInfo['aVersions'].length == 0) {
				oResult['aSkipped'].push({ 'sTable': 'sys_ws_operation', 'sKey': oOperationInfo['sName'], 'sSysId': oOperationInfo['sOperationId'], 'sReason': 'not part of the requested or an active API version' });
				continue;
			} // if no version
			var oMapEntry = this._getValue(oOperationInfo['sOperationId'], '', oOptions['oResourceConfigMap']);
			var oSelection = this._selectResource(String(grOperation.getValue('operation_script') || ''), oMapEntry, oOperationInfo['sHttpMethod']);
			oSelection['aWarnings'].forEach(function (sWarning) {
				oResult['aWarnings'].push({ 'sTable': 'sys_ws_operation', 'sKey': oOperationInfo['sName'], 'sSysId': oOperationInfo['sOperationId'], 'sReason': sWarning });
			}, this); // each selection warning
			if (!oSelection['bInScope']) {
				oResult['aSkipped'].push({ 'sTable': 'sys_ws_operation', 'sKey': oOperationInfo['sName'], 'sSysId': oOperationInfo['sOperationId'], 'sReason': oSelection['sReason'] });
				continue;
			} // if not in scope
			var aVariants = [];
			var sResolveError = '';
			oSelection['aConfigs'].some(function (sConfig) {
				var oResolve = this._resolveConfig(sConfig);
				if (!oResolve['oConfig']) {
					sResolveError = oResolve['sError'];
					return true;
				} // if config not resolved
				aVariants.push({ 'sConfigName': sConfig, 'oConfig': oResolve['oConfig'] });
			}, this); // each configuration
			if (sResolveError) {
				oResult['aSkipped'].push({ 'sTable': 'sys_ws_operation', 'sKey': oOperationInfo['sName'], 'sSysId': oOperationInfo['sOperationId'], 'sReason': sResolveError });
				oResult['aWarnings'].push({ 'sTable': 'sys_ws_operation', 'sKey': oOperationInfo['sName'], 'sSysId': oOperationInfo['sOperationId'], 'sReason': sResolveError });
				continue;
