				oAction['sAction'] = (aChanged.length > 0) ? 'update' : 'unchanged';
				oAction['aChangedFields'] = aChanged;
				oAction['oPrevious'] = oExisting;
			} // if conflict, foreign scope or ours
		} // if exists
		aActions.push(oAction);
		return oAction;
	}, // function _planRecord

	_normalizeBoolean: function (oValue) {
		if (!this._checkAccess(gs.getCallerScopeName())) { return; }
		return (['1', 'true'].indexOf(String(oValue)) != -1) ? 'true' : 'false';
	}, // function _normalizeBoolean

	_resolvedForCompare: function (oSpecification) {
		if (!this._checkAccess(gs.getCallerScopeName())) { return; }
		var oValues = JSON.parse(JSON.stringify(oSpecification['oValues']));
		var oReferences = oSpecification['oReferences'] || {};
		Object.keys(oReferences).forEach(function (sField) {
			oValues[sField] = oReferences[sField]['sKnownSysId'] || ('pending:' + oReferences[sField]['sName']);
		}); // each reference resolved to a known sys_id
		return oValues;
	}, // function _resolvedForCompare

	_diffApiPlan: function (oApi, oApiPlan, oOptions, oResult) {
		if (!this._checkAccess(gs.getCallerScopeName())) { return; }
		var aActions = [];
		var bFiltered = ((oOptions['aResourceIds'].length > 0) || (oOptions['sVersion'] !== ''));
		var oProcessedKeys = {};
		oApiPlan['aOperations'].forEach(function (oOperationInfo) {
			oProcessedKeys[oOperationInfo['sResourceKey']] = true;
		}); // each processed resource key
		var aExistingSchemas = this._readRecords('sys_ws_schema', 'api=' + oApi['sName'], ['name', 'api', 'api_path', 'schema', 'openapi_version', 'description']);
		var oExistingSchemas = {};
		aExistingSchemas.forEach(function (oSchema) {
			oExistingSchemas[oSchema['name']] = oSchema;
		}); // index schemas by name
		var oSchemaActions = {};
		Object.keys(oApiPlan['oSchemas']).forEach(function (sName) {
			var oPlanned = oApiPlan['oSchemas'][sName];
			var oExisting = oExistingSchemas[sName];
			oSchemaActions[sName] = this._planRecord(aActions, {
				'sTable': 'sys_ws_schema', 'sKey': oApi['sName'] + '|' + sName, 'iOrder': 10, 'oExisting': oExisting,
				'bGenerated': ((oExisting) && (sName.indexOf(this.sSchemaPrefix) == 0) && (this._isGenerated(oExisting['description']))),
				'bOverwriteManual': oOptions['bOverwriteManual'], 'aJsonFields': ['schema'],
				'oValues': { 'api': oApi['sName'], 'api_path': oApi['sApiPath'], 'name': sName, 'schema': oPlanned['sSchema'], 'openapi_version': this.sOpenApiVersion, 'description': this._withMarker(oPlanned['sDescription']) },
				'sReferenceName': sName
			}); // planned schema
		}, this); // each planned schema
		var oSchemaIds = {};
		aExistingSchemas.forEach(function (oSchema) {
			oSchemaIds[oSchema['sys_id']] = oSchema['name'];
		}); // index schema names by sys_id
		var fnSchemaReference = function (sSchemaName) {
			var oExisting = oExistingSchemas[sSchemaName];
			return { 'sName': sSchemaName, 'sKnownSysId': (oExisting) ? oExisting['sys_id'] : '' };
		}; // function fnSchemaReference
		var aResources = this._gtArray.unique(oApiPlan['aResourceVersions'].map(function (oResourceVersion) { return oResourceVersion['sApiResource']; }));
		var sResourceQuery = 'api_resourceIN' + aResources.join(',');
		var aSpecTables = [{ 'sTable': 'sys_ws_request_spec', 'aPlanned': oApiPlan['aRequestSpecs'], 'iOrder': 30 }, { 'sTable': 'sys_ws_response_spec', 'aPlanned': oApiPlan['aResponseSpecs'], 'iOrder': 40 }];
		var aRemainingSpecSchemaIds = [];
		aSpecTables.forEach(function (oSpecTable) {
			var bResponse = (oSpecTable['sTable'] == 'sys_ws_response_spec');
			var aFields = ['api', 'api_path', 'api_resource', 'version', 'http_method', 'schema', 'description'].concat((bResponse) ? ['http_status'] : []);
			var fnKey = function (oRecord) {
				return [oRecord['api_resource'], oRecord['version'], String(oRecord['http_method']).toUpperCase()].concat((bResponse) ? [String(oRecord['http_status'])] : []).join('|');
			}; // function fnKey
			var oExistingSpecs = {};
			var aExistingSpecs = (aResources.length > 0) ? this._readRecords(oSpecTable['sTable'], sResourceQuery, aFields) : [];
			aExistingSpecs.forEach(function (oSpec) {
				oExistingSpecs[fnKey(oSpec)] = oSpec;
			}); // index specs by key
			var oPlannedKeys = {};
			oSpecTable['aPlanned'].forEach(function (oPlanned) {
				var oValues = { 'api': oApi['sName'], 'api_path': oApi['sApiPath'], 'api_resource': oPlanned['sApiResource'], 'version': oPlanned['sVersion'], 'http_method': oPlanned['sHttpMethod'], 'description': this._withMarker(oPlanned['sDescription']) };
				if (bResponse) {
					oValues['http_status'] = String(oPlanned['iHttpStatus']);
				} // if response
				var sKey = fnKey(oValues);
				oPlannedKeys[sKey] = true;
				var oSchemaAction = oSchemaActions[oPlanned['sSchemaName']];
				if ((oSchemaAction) && ((oSchemaAction['sAction'] == 'conflict') || (oSchemaAction['sAction'] == 'warning'))) {
					aActions.push({ 'sTable': oSpecTable['sTable'], 'sKey': sKey, 'sAction': 'conflict', 'sReason': 'depends on schema ' + oPlanned['sSchemaName'] + ', which is not owned by the generator' });
					return;
				} // if schema not ours
				var oExisting = oExistingSpecs[sKey];
				this._planRecord(aActions, {
					'sTable': oSpecTable['sTable'], 'sKey': sKey, 'iOrder': oSpecTable['iOrder'], 'oExisting': oExisting,
					'bGenerated': ((oExisting) && (this._isGenerated(oExisting['description']))), 'bOverwriteManual': oOptions['bOverwriteManual'],
					'oValues': oValues, 'oReferences': { 'schema': fnSchemaReference(oPlanned['sSchemaName']) }
				}); // planned spec
			}, this); // each planned spec
			aExistingSpecs.forEach(function (oSpec) {
				var sKey = fnKey(oSpec);
				var bProcessed = oApiPlan['aResourceVersions'].some(function (oResourceVersion) {
					return ((oResourceVersion['sApiResource'] == oSpec['api_resource']) && (oResourceVersion['sVersion'] == oSpec['version']) && (oResourceVersion['sHttpMethod'] == String(oSpec['http_method']).toUpperCase()));
				}); // spec belongs to a processed resource version
				if ((oPlannedKeys[sKey]) || (!bProcessed) || (!this._isGenerated(oSpec['description']))) {
					if ((!oPlannedKeys[sKey]) && (oSpec['schema'])) {
						aRemainingSpecSchemaIds.push(oSpec['schema']);
					} // if spec stays and references a schema
					return;
				} // if planned, foreign or manual
				this._planStale(aActions, oSpecTable['sTable'], sKey, oSpec, oOptions, oSpecTable['iOrder']);
				if (oSpec['sys_scope'] != 'global') {
					aRemainingSpecSchemaIds.push(oSpec['schema']);
				} // if stale spec cannot be removed
			}, this); // each existing spec
		}, this); // each spec table
		this._countSchemaUsageOutsidePlan(oApi, aResources, aRemainingSpecSchemaIds);
		aExistingSchemas.forEach(function (oSchema) {
			if ((oApiPlan['oSchemas'].hasOwnProperty(oSchema['name'])) || (oSchema['name'].indexOf(this.sSchemaPrefix) != 0) || (!this._isGenerated(oSchema['description']))) {
				return;
			} // if planned or manual
			var bShared = (oSchema['name'] == this.sErrorSchemaName);
			var sResourceKey = oSchema['name'].substring(this.sSchemaPrefix.length).split('.')[0];
			if ((!bShared) && (!oProcessedKeys[sResourceKey])) {
				return;
			} // if schema of a resource not processed in this run
			if ((bShared) && ((bFiltered) || (aRemainingSpecSchemaIds.indexOf(oSchema['sys_id']) != -1))) {
				return;
			} // if shared schema may still be used
			if (aRemainingSpecSchemaIds.indexOf(oSchema['sys_id']) != -1) {
				oResult['aWarnings'].push({ 'sTable': 'sys_ws_schema', 'sKey': oApi['sName'] + '|' + oSchema['name'], 'sSysId': oSchema['sys_id'], 'sReason': 'stale schema is still referenced by a spec that is not generated; left alone' });
				return;
			} // if referenced elsewhere
			this._planStale(aActions, 'sys_ws_schema', oApi['sName'] + '|' + oSchema['name'], oSchema, oOptions, 10);
		}, this); // each existing schema
		this._diffQueryParameters(oApi, oApiPlan, oOptions, bFiltered, aActions);
		return aActions;
	}, // function _diffApiPlan

	// Specs of other resources may reference a generated schema; those references keep the schema alive.
	_countSchemaUsageOutsidePlan: function (oApi, aResources, aRemainingSpecSchemaIds) {
		if (!this._checkAccess(gs.getCallerScopeName())) { return; }
		['sys_ws_request_spec', 'sys_ws_response_spec'].forEach(function (sTable) {
			var sQuery = 'api=' + oApi['sName'] + ((aResources.length > 0) ? '^api_resourceNOT IN' + aResources.join(',') : '') + '^schemaISNOTEMPTY';
			this._readRecords(sTable, sQuery, ['schema']).forEach(function (oSpec) {
				aRemainingSpecSchemaIds.push(oSpec['schema']);
			}); // each spec outside the plan
		}, this); // each spec table
	}, // function _countSchemaUsageOutsidePlan

	_planStale: function (aActions, sTable, sKey, oExisting, oOptions, iOrder) {
		if (!this._checkAccess(gs.getCallerScopeName())) { return; }
		var oAction = { 'sTable': sTable, 'sKey': sKey, 'sSysId': oExisting['sys_id'], 'iOrder': iOrder };
		if (oExisting['sys_scope'] != 'global') {
			oAction['sAction'] = 'warning';
			oAction['sReason'] = 'stale generated record in scope ' + oExisting['sys_scope'] + '; left alone';
		} else if (oOptions['bRemoveStale']) {
			oAction['sAction'] = 'delete';
			oAction['sReason'] = 'no longer produced by the configuration';
		} else {
			oAction['sAction'] = 'warning';
			oAction['sReason'] = 'stale: no longer produced by the configuration (bRemoveStale is false)';
		} // if removable
		aActions.push(oAction);
	}, // function _planStale

	_diffQueryParameters: function (oApi, oApiPlan, oOptions, bFiltered, aActions) {
		if (!this._checkAccess(gs.getCallerScopeName())) { return; }
		var aExistingParameters = this._readRecords('sys_ws_query_parameter', 'web_service_definition=' + oApi['sSysId'], ['web_service_definition', 'name', 'short_description', 'example_value', 'required']);
		var oExistingParameters = {};
		var oParameterNamesById = {};
		aExistingParameters.forEach(function (oParameter) {
			oExistingParameters[oParameter['name']] = oParameter;
			oParameterNamesById[oParameter['sys_id']] = oParameter;
		}); // index parameters
		var oParameterActions = {};
		Object.keys(oApiPlan['oQueryParameters']).forEach(function (sName) {
			var oPlanned = oApiPlan['oQueryParameters'][sName];
			var oExisting = oExistingParameters[sName];
			oParameterActions[sName] = this._planRecord(aActions, {
				'sTable': 'sys_ws_query_parameter', 'sKey': oApi['sName'] + '|' + sName, 'iOrder': 20, 'oExisting': oExisting,
				'bGenerated': ((oExisting) && (this._isGenerated(oExisting['short_description']))), 'bOverwriteManual': oOptions['bOverwriteManual'], 'aBooleanFields': ['required'],
				'oValues': { 'web_service_definition': oApi['sSysId'], 'name': sName, 'short_description': oPlanned['sShortDescription'], 'example_value': oPlanned['sExampleValue'], 'required': (oPlanned['bRequired']) ? 'true' : 'false' },
				'sReferenceName': sName
			}); // planned parameter
		}, this); // each planned parameter
		var aOperationIds = oApiPlan['aOperations'].map(function (oOperationInfo) { return oOperationInfo['sOperationId']; });
		var aExistingMaps = this._readRecords('sys_ws_query_parameter_map', 'web_service_operationIN' + aOperationIds.join(','), ['web_service_operation', 'web_service_query_parameter']);
		var oExistingMaps = {};
		aExistingMaps.forEach(function (oMap) {
			var oParameter = oParameterNamesById[oMap['web_service_query_parameter']];
			oExistingMaps[oMap['web_service_operation'] + '|' + ((oParameter) ? oParameter['name'] : oMap['web_service_query_parameter'])] = oMap;
		}); // index maps by operation and parameter name
		var oPlannedMaps = {};
		oApiPlan['aParameterMaps'].forEach(function (oPlannedMap) {
			var sKey = oPlannedMap['sOperationId'] + '|' + oPlannedMap['sParameterName'];
			oPlannedMaps[sKey] = true;
			var oParameterAction = oParameterActions[oPlannedMap['sParameterName']];
			if ((oParameterAction) && ((oParameterAction['sAction'] == 'conflict') || (oParameterAction['sAction'] == 'warning'))) {
				aActions.push({ 'sTable': 'sys_ws_query_parameter_map', 'sKey': oPlannedMap['sOperationName'] + '|' + oPlannedMap['sParameterName'], 'sAction': 'conflict', 'sReason': 'depends on query parameter ' + oPlannedMap['sParameterName'] + ', which is not owned by the generator' });
				return;
			} // if parameter not ours
			var oExisting = oExistingMaps[sKey];
			var oExistingParameter = oExistingParameters[oPlannedMap['sParameterName']];
			aActions.push({
				'sTable': 'sys_ws_query_parameter_map', 'sKey': oPlannedMap['sOperationName'] + '|' + oPlannedMap['sParameterName'], 'iOrder': 50,
				'sAction': (oExisting) ? 'unchanged' : 'create', 'sSysId': (oExisting) ? oExisting['sys_id'] : '',
				'oValues': { 'web_service_operation': oPlannedMap['sOperationId'] },
				'oReferences': { 'web_service_query_parameter': { 'sName': oPlannedMap['sParameterName'], 'sKnownSysId': (oExistingParameter) ? oExistingParameter['sys_id'] : '' } }
			}); // planned map (ownership derives from the parameter, the table has no description)
		}, this); // each planned map
		var oParametersInUse = {};
		aExistingMaps.forEach(function (oMap) {
			var oParameter = oParameterNamesById[oMap['web_service_query_parameter']];
			var sKey = oMap['web_service_operation'] + '|' + ((oParameter) ? oParameter['name'] : '');
			if ((oPlannedMaps[sKey]) || (!oParameter) || (!this._isGenerated(oParameter['short_description']))) {
				return;
			} // if planned or manual
			this._planStale(aActions, 'sys_ws_query_parameter_map', sKey, oMap, oOptions, 50);
		}, this); // each existing map of a processed resource
		this._readRecords('sys_ws_query_parameter_map', 'web_service_query_parameter.web_service_definition=' + oApi['sSysId'] + '^web_service_operationNOT IN' + aOperationIds.join(','), ['web_service_query_parameter']).forEach(function (oMap) {
			oParametersInUse[oMap['web_service_query_parameter']] = true;
		}); // parameters still mapped to resources outside this run
		aExistingParameters.forEach(function (oParameter) {
			if ((oApiPlan['oQueryParameters'].hasOwnProperty(oParameter['name'])) || (!this._isGenerated(oParameter['short_description']))) {
				return;
			} // if planned or manual
			if ((bFiltered) || (oParametersInUse[oParameter['sys_id']])) {
				return;
			} // if another resource may still use it
			this._planStale(aActions, 'sys_ws_query_parameter', oApi['sName'] + '|' + oParameter['name'], oParameter, oOptions, 20);
		}, this); // each existing parameter
	}, // function _diffQueryParameters

	/***********************************************************************************************************
	*	Reporting and writing
	************************************************************************************************************/

	_reportActions: function (aActions, oResult) {
		if (!this._checkAccess(gs.getCallerScopeName())) { return; }
		var oTargets = { 'create': 'aCreated', 'update': 'aUpdated', 'delete': 'aDeleted', 'unchanged': 'aUnchanged', 'conflict': 'aConflicts', 'warning': 'aWarnings' };
		aActions.forEach(function (oAction) {
			var sReason = oAction['sReason'] || '';
			if ((oAction['sAction'] == 'update') && (oAction['aChangedFields'])) {
				sReason = 'changed: ' + oAction['aChangedFields'].join(', ');
			} // if update
			var oEntry = { 'sTable': oAction['sTable'], 'sKey': oAction['sKey'] };
			if (oAction['sSysId']) {
				oEntry['sSysId'] = oAction['sSysId'];
			} // if sys id
			if (sReason) {
				oEntry['sReason'] = sReason;
			} // if reason
			oResult[oTargets[oAction['sAction']]].push(oEntry);
		}, this); // each action
	}, // function _reportActions

	_executeActions: function (aActions, oResult) {
		if (!this._checkAccess(gs.getCallerScopeName())) { return; }
		var oCreatedIds = { 'sys_ws_schema': {}, 'sys_ws_query_parameter': {} };
		var aUndo = [];
		var aWrites = aActions.filter(function (oAction) {
			return ((oAction['sAction'] == 'create') || (oAction['sAction'] == 'update'));
		}).sort(function (oFirst, oSecond) {
			return oFirst['iOrder'] - oSecond['iOrder'];
		}); // creates and updates, referenced tables first
		var aDeletes = aActions.filter(function (oAction) {
			return (oAction['sAction'] == 'delete');
		}).sort(function (oFirst, oSecond) {
			return oSecond['iOrder'] - oFirst['iOrder'];
		}); // deletes, referencing tables first
		var bFailed = aWrites.some(function (oAction) {
			var oValues = JSON.parse(JSON.stringify(oAction['oValues']));
			var bResolved = Object.keys(oAction['oReferences'] || {}).every(function (sField) {
				var oReference = oAction['oReferences'][sField];
				var sTargetTable = (sField == 'schema') ? 'sys_ws_schema' : 'sys_ws_query_parameter';
				oValues[sField] = oReference['sKnownSysId'] || oCreatedIds[sTargetTable][oReference['sName']] || '';
				return (oValues[sField] !== '');
			}); // each reference
			if (!bResolved) {
				oResult['bIsOk'] = false;
				oResult['sErrorMessage'] = 'Write failed for ' + oAction['sTable'] + ' ' + oAction['sKey'] + ': referenced record was not written';
				return true;
			} // if reference missing
			var grRecord = new GlideRecord(oAction['sTable']);
			var sSysId = '';
			if (oAction['sAction'] == 'create') {
				grRecord.initialize();
				Object.keys(oValues).forEach(function (sField) { grRecord.setValue(sField, oValues[sField]); });
				sSysId = String(grRecord.insert() || '');
				if (sSysId) {
					aUndo.push({ 'sAction': 'delete', 'sTable': oAction['sTable'], 'sSysId': sSysId });
				} // if inserted
			} else if (grRecord.get(oAction['sSysId'])) {
				var oPrevious = {};
				Object.keys(oValues).forEach(function (sField) {
					oPrevious[sField] = grRecord.getValue(sField);
					grRecord.setValue(sField, oValues[sField]);
				}); // each value
				sSysId = String(grRecord.update() || '');
				if (sSysId) {
					aUndo.push({ 'sAction': 'restore', 'sTable': oAction['sTable'], 'sSysId': sSysId, 'oValues': oPrevious });
				} // if updated
			} // if create or update
			if (!sSysId) {
				oResult['bIsOk'] = false;
				oResult['sErrorMessage'] = 'Write failed for ' + oAction['sTable'] + ' ' + oAction['sKey'] + ': ' + String(grRecord.getLastErrorMessage() || 'aborted by a business rule or data policy');
				return true;
			} // if write failed
			if ((oAction['sReferenceName']) && (oCreatedIds.hasOwnProperty(oAction['sTable']))) {
				oCreatedIds[oAction['sTable']][oAction['sReferenceName']] = sSysId;
			} // if referenced later
			oAction['sSysId'] = sSysId;
		}, this); // each write
		if (bFailed) {
			this._undo(aUndo);
			oResult['sErrorMessage'] += '; the changes of this run were reverted';
			return;
		} // if a write failed
		aDeletes.forEach(function (oAction) {
			var grRecord = new GlideRecord(oAction['sTable']);
			if ((grRecord.get(oAction['sSysId'])) && (!grRecord.deleteRecord())) {
				oAction['sAction'] = 'warning';
				oAction['sReason'] = 'stale record could not be deleted';
			} // if delete failed
		}, this); // each delete
		this._reportActions(aActions, oResult);
	}, // function _executeActions

	_undo: function (aUndo) {
		if (!this._checkAccess(gs.getCallerScopeName())) { return; }
		aUndo.reverse().forEach(function (oUndo) {
			var grRecord = new GlideRecord(oUndo['sTable']);
			if (!grRecord.get(oUndo['sSysId'])) {
				return;
			} // if gone
			if (oUndo['sAction'] == 'delete') {
				grRecord.deleteRecord();
			} else {
				Object.keys(oUndo['oValues']).forEach(function (sField) { grRecord.setValue(sField, oUndo['oValues'][sField]); });
				grRecord.update();
			} // if delete or restore
		}); // each undo step
	}, // function _undo

	type: 'GlobalToolsScriptedRESTDoc',
	version: '2.1.5',
	author: 'Tom Hauri',
	email: 'tom@hauri.biz'

};
